export interface DurableSandboxTools {
  create(
    idOrOptions: StepOptionsOrId,
    options: SandboxCreateOptions,
  ): Promise<DurableSandbox>;
  list(
    idOrOptions: StepOptionsOrId,
    options?: SandboxListOptions,
