    if (retainedTotal > maxDurableSandboxExecOutputBytes) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "retained output exceeds the durable sandbox exec limit",
        path: ["output", "retainedBytes"],
