s=open(p).read()
new='''describe("inngest.sandboxes running wait", () => {
  const { kind: _kind, version: _version, ...resource } = sandboxRef;
  const respond = (status: string, error?: string) =>
    Response.json({
      data: { ...resource, status, ...(error && { error }) },
    });

  test("Create with runningTimeout polls Get without re-sending Create", async () => {
    vi.useFakeTimers();
    try {
      const calls: string[] = [];
      const statuses = ["STARTING", "RUNNING"];
      const client = createSandboxClient({
        baseUrl: () => "https://api.example.test",
        apiKey: () => "signkey-test",
        headers: () => ({}),
        fetch: () => async (url, init) => {
          calls.push(`${init?.method} ${new URL(String(url)).pathname}`);
          if (init?.method === "POST") {
            expect(JSON.parse(String(init.body))).toEqual(createOptions);
            return respond("STARTING");
          }
          return respond(statuses.shift()!);
        },
      });
      const promise = client.create({ ...createOptions, runningTimeout: "5s" });
      await vi.advanceTimersByTimeAsync(2_000);
      await expect(promise).resolves.toMatchObject({ status: "RUNNING" });
      expect(calls).toEqual([
        "POST /v2/sandboxes",
        `GET /v2/sandboxes/${sandboxId}`,
        `GET /v2/sandboxes/${sandboxId}`,
      ]);
    } finally {
      vi.useRealTimers();
    }
  });

  test("waitUntilRunning reports failed and timed out starts", async () => {
    vi.useFakeTimers();
    try {
      let status = "FAILED";
      const client = createSandboxClient({
        baseUrl: () => "https://api.example.test",
        apiKey: () => "signkey-test",
        headers: () => ({}),
        fetch: () => async (_url, init) =>
          init?.method === "POST"
            ? respond("STARTING")
            : respond(status, status === "FAILED" ? "boom" : undefined),
      });
      const sandbox = await client.create(createOptions);
      const failed = expect(
        sandbox.waitUntilRunning({ timeout: "5s" }),
      ).rejects.toMatchObject({
        action: "waitUntilRunning",
        code: "sandbox_start_failed",
        retryable: false,
        sandboxId,
        message: "Sandbox entered FAILED before reaching RUNNING",
        details: [{ status: "FAILED", error: "boom" }],
      });
      await vi.advanceTimersByTimeAsync(1_000);
      await failed;

      status = "STARTING";
      const timedOut = expect(
        sandbox.waitUntilRunning({ timeout: "2s" }),
      ).rejects.toMatchObject({
        code: "sandbox_start_timed_out",
        message: "Sandbox did not reach RUNNING within 2000 milliseconds",
        details: [{ status: "STARTING", timeoutMs: 2000 }],
      });
      await vi.advanceTimersByTimeAsync(3_000);
      await timedOut;
    } finally {
      vi.useRealTimers();
    }
  });

  test("waitUntilRunning rejects unknown keys and long timeouts", async () => {
    const client = createSandboxClient({
      baseUrl: () => "https://api.example.test",
      apiKey: () => "signkey-test",
      headers: () => ({}),
      fetch: () => async () => respond("RUNNING"),
    });
    const sandbox = await client.create(createOptions);
    await expect(
      sandbox.waitUntilRunning({ timeout: "5s", extra: 1 } as never),
    ).rejects.toBeInstanceOf(SandboxValidationError);
    await expect(
      sandbox.waitUntilRunning({ timeout: "6m" }),
    ).rejects.toBeInstanceOf(SandboxValidationError);
